create extension if not exists pgcrypto;
create type public.user_role as enum ('DIRECTOR','REGISTERED_MANAGER','OPERATIONS_MANAGER','CLINICAL_LEAD','SAFEGUARDING_LEAD','STAFF');
create type public.record_status as enum ('OPEN','UNDER_INVESTIGATION','ACTION_REQUIRED','CLOSED');
create table public.staff(id uuid primary key default gen_random_uuid(),auth_user_id uuid unique,employee_number text unique not null,first_name text not null,last_name text not null,role_title text not null,user_role public.user_role not null default 'STAFF',active boolean not null default true,hcpc_number text,nmc_number text,dbs_expiry date,driving_licence_expiry date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.shifts(id uuid primary key default gen_random_uuid(),call_sign text not null,area text not null,start_at timestamptz not null,end_at timestamptz not null,status text not null default 'PLANNED',created_at timestamptz not null default now());
create table public.shift_assignments(id uuid primary key default gen_random_uuid(),shift_id uuid not null references public.shifts(id) on delete cascade,staff_id uuid not null references public.staff(id),position text not null,created_at timestamptz not null default now(),unique(shift_id,staff_id));
create table public.incidents(id uuid primary key default gen_random_uuid(),reference text unique not null,category text not null,status public.record_status not null default 'OPEN',title text not null,description text,reported_by uuid references public.staff(id),occurred_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_user_id uuid,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.staff enable row level security;alter table public.shifts enable row level security;alter table public.shift_assignments enable row level security;alter table public.incidents enable row level security;alter table public.audit_logs enable row level security;
create or replace function public.current_staff_role() returns public.user_role language sql stable security definer set search_path=public as $$select user_role from public.staff where auth_user_id=auth.uid() and active=true limit 1$$;
create policy "authenticated staff can read staff directory" on public.staff for select to authenticated using(true);
create policy "operations can manage shifts" on public.shifts for all to authenticated using(public.current_staff_role() in ('DIRECTOR','REGISTERED_MANAGER','OPERATIONS_MANAGER')) with check(public.current_staff_role() in ('DIRECTOR','REGISTERED_MANAGER','OPERATIONS_MANAGER'));
create policy "staff can read assigned shifts" on public.shift_assignments for select to authenticated using(staff_id in(select id from public.staff where auth_user_id=auth.uid()) or public.current_staff_role() in ('DIRECTOR','REGISTERED_MANAGER','OPERATIONS_MANAGER'));
create policy "governance users can manage incidents" on public.incidents for all to authenticated using(public.current_staff_role() in ('DIRECTOR','REGISTERED_MANAGER','CLINICAL_LEAD','SAFEGUARDING_LEAD')) with check(public.current_staff_role() in ('DIRECTOR','REGISTERED_MANAGER','CLINICAL_LEAD','SAFEGUARDING_LEAD'));
create policy "authorized users can read audit logs" on public.audit_logs for select to authenticated using(public.current_staff_role() in ('DIRECTOR','REGISTERED_MANAGER'));
create index shifts_start_at_idx on public.shifts(start_at);create index incidents_status_idx on public.incidents(status);create index audit_logs_created_at_idx on public.audit_logs(created_at);
